DO $$ DECLARE d text; BEGIN SELECT pg_get_constraintdef(oid) INTO STRICT d FROM pg_constraint WHERE conrelid='cmd_command'::regclass AND conname='cmd_command_command_type_check'; ALTER TABLE cmd_command DROP CONSTRAINT cmd_command_command_type_check; EXECUTE format('ALTER TABLE cmd_command ADD CONSTRAINT cmd_command_command_type_check %s',replace(d,'CHECK (','CHECK (command_type=''resolve_survival_task'' OR ')); END $$;
CREATE TABLE cmd_survival_task_receipt(command_id bigint PRIMARY KEY REFERENCES cmd_command(command_id),campaign_id bigint NOT NULL REFERENCES camp_campaign(campaign_id),actor_id bigint NOT NULL,operation_rule_id bigint NOT NULL,operation_code text NOT NULL,objective_reference text NOT NULL CHECK(btrim(objective_reference)<>''),location_id bigint,opportunity_available boolean NOT NULL,automatic_failure boolean NOT NULL,task_command_id bigint UNIQUE REFERENCES cmd_actor_task_receipt(command_id),check_total smallint,effect smallint,succeeded boolean NOT NULL,FOREIGN KEY(actor_id,campaign_id) REFERENCES actor_actor(actor_id,campaign_id),FOREIGN KEY(location_id,campaign_id) REFERENCES loc_location(location_id,campaign_id),FOREIGN KEY(operation_rule_id,operation_code) REFERENCES rule_survival_operation(rule_id,operation_code),CHECK((automatic_failure AND NOT opportunity_available AND task_command_id IS NULL AND check_total IS NULL AND effect IS NULL AND NOT succeeded) OR (NOT automatic_failure AND opportunity_available AND task_command_id IS NOT NULL AND check_total IS NOT NULL AND effect IS NOT NULL)));
